INSERT INTO `questions` VALUES (6,31,88,'Qu\'est-ce qu\'un Network Security Group (NSG) dans Azure ?','qcm',2.00,1,NULL),(7,31,88,'À quelle(s) ressource(s) peut-on associer un NSG dans Azure ?','qcm',2.00,2,NULL),(8,31,88,'Pour le trafic ENTRANT vers une VM, dans quel ordre les NSG sont-ils évalués si un NSG est associé au sous-réseau ET à la NIC ?','qcm',2.00,3,NULL),(9,31,88,'Quelle commande Azure CLI crée un NSG nommé \"MonNSG\" dans le groupe de ressources \"MonRG\" ?','qcm',2.00,4,NULL),(10,31,88,'Combien de règles par défaut (default security rules) contient un NSG nouvellement créé dans Azure ?','qcm',2.00,5,NULL),(11,31,88,'Quelle commande PowerShell (module Az) affiche toutes les règles de sécurité d\'un NSG nommé \"MonNSG\" ?','qcm',2.00,6,NULL),(12,31,88,'Quel est le rôle principal d\'un Application Security Group (ASG) dans Azure ?','qcm',2.00,7,NULL),(13,31,88,'Dans une règle NSG, vous souhaitez autoriser le trafic HTTP (port 80) depuis le groupe \"WebServers\" (ASG) vers le groupe \"AppServers\" (ASG). Quelle configuration est correcte ?','qcm',2.00,8,NULL),(14,31,88,'Quelle commande Azure CLI ajoute une règle NSG autorisant le HTTPS entrant (port 443, priorité 300) ?','qcm',2.00,9,NULL),(15,31,88,'Quelle affirmation concernant les ASG et NSG est CORRECTE ?','qcm',2.00,10,NULL),(26,31,88,'Qu\'est-ce qu\'Azure Policy ?','qcm',2.00,1,NULL),(27,31,88,'Quel langage/format est utilisé pour définir une Azure Policy ?','qcm',2.00,2,NULL),(28,31,88,'Qu\'est-ce qu\'un \'scope\' (étendue) dans le contexte d\'Azure Policy ?','qcm',2.00,3,NULL),(29,31,88,'Quel est l\'effet (effect) d\'une Azure Policy qui empêche la création d\'une ressource non conforme ?','qcm',2.00,4,NULL),(30,31,88,'Quelle est la différence entre une \'Policy Definition\' et une \'Policy Assignment\' ?','qcm',2.00,5,NULL),(31,31,88,'Qu\'est-ce qu\'une \'Initiative\' (Policy Set Definition) dans Azure Policy ?','qcm',2.00,6,NULL),(32,31,88,'Lorsqu\'une Azure Policy avec l\'effet \'Audit\' est assignée, que se passe-t-il quand une ressource non conforme est créée ?','qcm',2.00,7,NULL),(33,31,88,'Comment fonctionne l\'héritage du scope lors de l\'assignation d\'une Azure Policy à un Management Group ?','qcm',2.00,8,NULL),(34,31,88,'Quel effet Azure Policy permet d\'ajouter automatiquement un tag manquant à une ressource lors de son déploiement sans bloquer la création ?','qcm',2.00,9,NULL),(35,31,88,'Dans une définition Azure Policy, quelle est la logique d\'évaluation lorsqu\'on utilise l\'opérateur logique \'allOf\' dans la condition (policy rule) ?','qcm',2.00,10,NULL),(36,31,88,'Qu\'est-ce qu\'Azure Key Vault ?','qcm',2.00,1,NULL),(37,31,88,'Quels sont les trois principaux types d\'objets gérés par Azure Key Vault ?','qcm',2.00,2,NULL),(38,31,88,'Quelle commande Azure CLI permet de créer un nouveau Key Vault ?','qcm',2.00,3,NULL),(39,31,88,'Quelle commande Azure CLI permet de stocker un secret dans un Key Vault existant ?','qcm',2.00,4,NULL),(40,31,88,'Quelle cmdlet PowerShell permet de récupérer un secret depuis Azure Key Vault ?','qcm',2.00,5,NULL),(41,31,88,'Quel mécanisme de contrôle d\'accès est recommandé par Microsoft pour gérer les permissions sur Azure Key Vault ?','qcm',2.00,6,NULL),(42,31,88,'Quelle est la différence principale entre les niveaux de tarification « Standard » et « Premium » d\'Azure Key Vault ?','qcm',2.00,7,NULL),(43,31,88,'Qu\'est-ce que la fonctionnalité « Soft Delete » (suppression réversible) dans Azure Key Vault ?','qcm',2.00,8,NULL),(44,31,88,'Quelle commande PowerShell permet de créer un Azure Key Vault avec la protection contre la purge activée ?','qcm',2.00,9,NULL),(45,31,88,'Vous souhaitez autoriser une application à accéder aux secrets d\'un Key Vault en utilisant Azure RBAC. Quel rôle intégré devez-vous attribuer au principal de service de l\'application pour qu\'il puisse uniquement lire les secrets, sans les modifier ?','qcm',2.00,10,NULL),(46,31,88,'Que désigne-t-on par « données en repos » (data at rest) ?','qcm',2.00,1,NULL),(47,31,88,'Quel algorithme de chiffrement symétrique est utilisé par Azure pour le chiffrement au repos ?','qcm',2.00,2,NULL),(48,31,88,'Concernant le chiffrement au repos sur Azure, quelle affirmation est correcte ?','qcm',2.00,3,NULL),(49,31,88,'Quelle technologie Azure est utilisée pour chiffrer les disques OS et données attachés aux machines virtuelles ?','qcm',2.00,4,NULL),(50,31,88,'Quelle technologie de chiffrement sous-jacente Azure Disk Encryption utilise-t-il sur les systèmes Linux ?','qcm',2.00,5,NULL),(51,31,88,'Quel est le rôle d\'Azure Key Vault dans la stratégie de chiffrement au repos ?','qcm',2.00,6,NULL),(52,31,88,'Quelle est la différence principale entre les clés PMK (Platform-managed keys) et CMK (Customer-managed keys) ?','qcm',2.00,7,NULL),(53,31,88,'Dans le mécanisme d\'envelope encryption utilisé par Azure, quel est le rôle respectif de la CMK et de la DEK ?','qcm',2.00,8,NULL),(54,31,88,'Quelle caractéristique distingue les Customer-provided keys (CPK) des Customer-managed keys (CMK) ?','qcm',2.00,9,NULL),(55,31,88,'Une entreprise soumise aux réglementations RGPD et PCI-DSS souhaite déployer une architecture Azure SQL avec un contrôle total sur le chiffrement. Quelle combinaison de technologies et de gestion des clés est la plus appropriée ?','qcm',2.00,10,NULL),(96,31,88,'Qu\'est-ce que Microsoft Defender for Cloud ?','qcm',2.00,1,NULL),(97,31,88,'Quel est le principe fondamental de l\'accès Just-In-Time (JIT) pour les machines virtuelles Azure ?','qcm',2.00,2,NULL),(98,31,88,'Qu\'est-ce qu\'Azure Disk Encryption (ADE) ?','qcm',2.00,3,NULL),(99,31,88,'Quel est le rôle principal d\'Azure Bastion ?','qcm',2.00,4,NULL),(100,31,88,'Quelle commande PowerShell permet d\'activer l\'accès JIT sur une machine virtuelle Azure ?','qcm',2.00,5,NULL),(101,31,88,'Quelle commande Azure CLI permet d\'activer Azure Disk Encryption sur une machine virtuelle Windows existante ?','qcm',2.00,6,NULL),(102,31,88,'Quelle commande Azure CLI permet 